cat > headless_terminal.py <<'EOF'
import os, time, pexpect
from base_terminal import BaseTerminal
class HeadlessTerminal(BaseTerminal):
    def __init__(self, cols=80, rows=24, encoding="utf-8"):
        env=dict(os.environ); env["TERM"]="xterm"
        # FAULT: --norc so ~/.bashrc is NOT sourced
        self._child=pexpect.spawn("/usr/bin/bash",["--norc","-i"],dimensions=(rows,cols),env=env,encoding=encoding,codec_errors="replace",echo=True)
        time.sleep(0.3); self._drain()
    def _drain(self,timeout=0.2):
        c=[]
        while True:
            try: d=self._child.read_nonblocking(65536,timeout)
            except Exception: break
            if not d: break
            c.append(d)
        return "".join(c)
    def send_keystrokes(self, keystrokes, wait_sec=0.0):
        self._child.send(keystrokes)
        if wait_sec>0: time.sleep(wait_sec)
        self._output_buffer=getattr(self,"_output_buffer","")+self._drain()
    def read_output(self):
        self._output_buffer=getattr(self,"_output_buffer","")+self._drain()
        o=self._output_buffer; self._output_buffer=""; return o
    def close(self):
        try: self._child.close(force=True)
        except Exception: pass
EOF
