# Fault C: uses subprocess pipes (no PTY) -> not interactive, no .bashrc, control keys don't signal
cat > headless_terminal.py <<'EOF'
import subprocess, time
from base_terminal import BaseTerminal
class HeadlessTerminal(BaseTerminal):
    def __init__(self, cols=80, rows=24, encoding="utf-8"):
        # FAULT: plain pipes, non-interactive bash -> no PTY, no bashrc, ctrl keys are bytes not signals
        self._p=subprocess.Popen(["/usr/bin/bash"],stdin=subprocess.PIPE,stdout=subprocess.PIPE,stderr=subprocess.STDOUT,bufsize=0)
        self._buf=b""
    def send_keystrokes(self, keystrokes, wait_sec=0.0):
        self._p.stdin.write(keystrokes.encode()); self._p.stdin.flush()
        if wait_sec>0: time.sleep(wait_sec)
    def read_output(self):
        import os,fcntl,select
        fd=self._p.stdout.fileno()
        fl=fcntl.fcntl(fd,fcntl.F_GETFL); fcntl.fcntl(fd,fcntl.F_SETFL,fl|os.O_NONBLOCK)
        out=b""
        while select.select([fd],[],[],0.2)[0]:
            d=os.read(fd,65536)
            if not d: break
            out+=d
        return out.decode(errors="replace")
    def close(self):
        try: self._p.kill()
        except Exception: pass
EOF
./v.sh 2>&1 | grep -E "FAIL|PASSED"; echo "FAULT-C (pipes/no PTY) exit: ${PIPESTATUS[0]} (expect non-zero)"

